-- =============================================================
-- 099 — Migrate /land-of-legends-transfer into landing_pages
-- =============================================================
-- Moves the hardcoded page at src/app/[locale]/land-of-legends-transfer/
-- into the admin-editable landing_pages table, so it renders through the
-- same template as the blog and region pages and can be edited from the
-- panel. Every word of the old page is preserved: the meta title and
-- description are set as explicit overrides (meta_title_*/meta_description_*)
-- so the Google snippet does not change, the opening paragraph becomes the
-- page's short intro, and the "why book" list plus the FAQ become the
-- article body. The URL does not change — this only takes effect once the
-- hardcoded route folder is removed in a follow-up commit.
--
-- Safe to run twice: does nothing if the row already exists.

INSERT INTO landing_pages (slug, label, is_published, cta_region_slug, image_url, image_alt, sort_order, h1_en, intro_en, content_en, meta_title_en, meta_description_en, h1_de, intro_de, content_de, meta_title_de, meta_description_de, h1_pl, intro_pl, content_pl, meta_title_pl, meta_description_pl, h1_ru, intro_ru, content_ru, meta_title_ru, meta_description_ru, h1_tr, intro_tr, content_tr, meta_title_tr, meta_description_tr, h1_nl, intro_nl, content_nl, meta_title_nl, meta_description_nl, h1_ro, intro_ro, content_ro, meta_title_ro, meta_description_ro)
SELECT 'land-of-legends-transfer', 'Land of Legends Transfer', true, 'belek', '/images/regions/belek-golf.jpg', 'Land of Legends Theme Park transfer from Antalya Airport', 100, 'Antalya Airport → Land of Legends Transfer', 'Private VIP transfer to the most popular theme park in Turkey. Fixed price, no waiting.', '<p>Land of Legends Theme Park is located in Belek, approximately 35 km east of Antalya Airport. With TORVIAN''s private VIP transfer service, you can reach the park in around 30 minutes in complete comfort — no taxis, no waiting, no surprises.</p><h2>Why Book with TORVIAN?</h2><ul><li>Direct door-to-door transfer from Antalya Airport (AYT)</li><li>Fixed price — no meter, no surge pricing</li><li>Meet &amp; greet with name sign at arrivals hall</li><li>Free flight tracking — we wait if your flight is delayed</li><li>Mercedes Vito VIP with air conditioning &amp; free Wi-Fi</li><li>Free cancellation up to 24 hours before</li><li>24/7 WhatsApp support in English, German, Polish, Russian</li></ul><h2>Frequently Asked Questions</h2><h3>How far is Land of Legends from Antalya Airport?</h3><p>Land of Legends Theme Park in Belek is approximately 35 km from Antalya Airport (AYT). The transfer takes around 30 minutes by private vehicle.</p><h3>How much does a transfer to Land of Legends cost?</h3><p>Our fixed-price transfer to Land of Legends starts from a set rate per vehicle (not per person). The exact price is shown during booking. No hidden fees.</p><h3>Can I book a return transfer from Land of Legends to Antalya Airport?</h3><p>Yes, we offer round-trip transfers. You can select return transfer during booking and get a discounted combined rate.</p><h3>Does the driver wait at the park entrance?</h3><p>For hotel pickups and return transfers, your driver will be at the meeting point at the scheduled time. For airport arrivals, we track your flight and meet you at the arrivals hall.</p>', 'Land of Legends Transfer | Antalya Airport to Land of Legends', 'Private VIP transfer from Antalya Airport to Land of Legends Theme Park Belek. ~30 min, 35 km. Fixed price, meet & greet, free flight tracking. Book online.', 'Flughafen Antalya → Land of Legends Transfer', 'Privater VIP-Transfer in den beliebtesten Freizeitpark der Türkei. Festpreis, keine Wartezeit.', '<p>Der Land of Legends Theme Park befindet sich in Belek, etwa 35 km östlich vom Flughafen Antalya. Mit dem privaten VIP-Transfer von TORVIAN erreichen Sie den Park in etwa 30 Minuten — kein Taxi, keine Wartezeit, keine Überraschungen.</p><h2>Warum TORVIAN wählen?</h2><ul><li>Direkttransfer vom Flughafen Antalya (AYT)</li><li>Festpreis — kein Taxameter, keine Preisschwankungen</li><li>Meet &amp; Greet mit Namensschild in der Ankunftshalle</li><li>Kostenlose Flugverfolgung — wir warten bei Verspätung</li><li>Mercedes Vito VIP mit Klimaanlage &amp; kostenlosem WLAN</li><li>Kostenlose Stornierung bis 24 Stunden vorher</li><li>24/7 WhatsApp-Support auf Deutsch</li></ul><h2>Häufig gestellte Fragen</h2><h3>Wie weit ist der Land of Legends vom Flughafen Antalya entfernt?</h3><p>Der Land of Legends Freizeitpark in Belek liegt etwa 35 km vom Flughafen Antalya (AYT) entfernt. Die Fahrt dauert mit einem Privatfahrzeug ca. 30 Minuten.</p><h3>Was kostet ein Transfer zum Land of Legends?</h3><p>Unser Festpreistransfer zum Land of Legends beginnt ab einem festen Preis pro Fahrzeug (nicht pro Person). Der genaue Preis wird bei der Buchung angezeigt. Keine versteckten Gebühren.</p><h3>Kann ich einen Rücktransfer vom Land of Legends zum Flughafen buchen?</h3><p>Ja, wir bieten Hin- und Rücktransfers an. Beim Buchen können Sie den Rücktransfer auswählen und erhalten einen vergünstigten Kombinationspreis.</p><h3>Wartet der Fahrer am Parkeingang?</h3><p>Bei Hotel-Abholungen und Rücktransfers ist Ihr Fahrer zum vereinbarten Zeitpunkt am Treffpunkt. Bei Flughafenankünften verfolgen wir Ihren Flug und empfangen Sie in der Ankunftshalle.</p>', 'Land of Legends Transfer | Flughafen Antalya nach Land of Legends', 'Privater VIP-Transfer vom Flughafen Antalya zum Land of Legends Freizeitpark Belek. ~30 Min, 35 km. Festpreis, Meet & Greet, kostenlose Flugverfolgung. Online buchen.', 'Lotnisko Antalya → Transfer Land of Legends', 'Prywatny transfer VIP do najpopularniejszego parku rozrywki w Turcji. Stała cena, bez czekania.', '<p>Park rozrywki Land of Legends znajduje się w Belek, około 35 km na wschód od lotniska Antalya. Dzięki prywatnemu transferowi VIP TORVIAN dotrzesz do parku w około 30 minut — bez taksówek, bez czekania, bez niespodzianek.</p><h2>Dlaczego TORVIAN?</h2><ul><li>Bezpośredni transfer z lotniska Antalya (AYT)</li><li>Stała cena — bez licznika, bez zmiennych opłat</li><li>Meet &amp; greet z tabliczką z nazwiskiem w hali przylotów</li><li>Bezpłatne śledzenie lotu — czekamy przy opóźnieniu</li><li>Mercedes Vito VIP z klimatyzacją i bezpłatnym Wi-Fi</li><li>Bezpłatna anulacja do 24 godzin wcześniej</li><li>Wsparcie WhatsApp 24/7 po polsku</li></ul><h2>Najczęściej zadawane pytania</h2><h3>Jak daleko jest Land of Legends od lotniska Antalya?</h3><p>Park rozrywki Land of Legends w Belek leży około 35 km od lotniska Antalya (AYT). Transfer prywatnym pojazdem trwa około 30 minut.</p><h3>Ile kosztuje transfer do Land of Legends?</h3><p>Nasz transfer w stałej cenie do Land of Legends zaczyna się od ustalonej stawki za pojazd (nie za osobę). Dokładna cena jest widoczna podczas rezerwacji. Brak ukrytych opłat.</p><h3>Czy mogę zarezerwować transfer powrotny z Land of Legends na lotnisko?</h3><p>Tak, oferujemy transfery w obie strony. Możesz wybrać transfer powrotny podczas rezerwacji i otrzymać zniżkę na kombinację.</p><h3>Czy kierowca czeka przy wejściu do parku?</h3><p>Przy odbiorach z hotelu i transferach powrotnych kierowca będzie na miejscu spotkania o umówionej godzinie. Przy przylocie śledzimy Twój lot i czekamy w hali przylotów.</p>', 'Transfer Land of Legends | Lotnisko Antalya do Land of Legends', 'Prywatny transfer VIP z lotniska Antalya do parku rozrywki Land of Legends w Belek. ~30 min, 35 km. Stała cena, meet & greet, śledzenie lotu. Rezerwuj online.', 'Аэропорт Анталья → Трансфер Land of Legends', 'Частный VIP-трансфер в самый популярный парк развлечений Турции. Фиксированная цена, без ожидания.', '<p>Парк развлечений Land of Legends расположен в Белеке, примерно в 35 км к востоку от аэропорта Анталья. С частным VIP-трансфером TORVIAN вы доберётесь до парка примерно за 30 минут — без такси, без ожидания, без сюрпризов.</p><h2>Почему TORVIAN?</h2><ul><li>Прямой трансфер из аэропорта Анталья (AYT)</li><li>Фиксированная цена — без счётчика, без скачков цены</li><li>Встреча с табличкой с именем в зале прилёта</li><li>Бесплатное отслеживание рейса — ждём при задержке</li><li>Mercedes Vito VIP с кондиционером и бесплатным Wi-Fi</li><li>Бесплатная отмена за 24 часа до поездки</li><li>Поддержка WhatsApp 24/7 на русском языке</li></ul><h2>Часто задаваемые вопросы</h2><h3>Как далеко Land of Legends от аэропорта Анталья?</h3><p>Парк развлечений Land of Legends в Белеке находится примерно в 35 км от аэропорта Анталья (AYT). Поездка на частном автомобиле занимает около 30 минут.</p><h3>Сколько стоит трансфер в Land of Legends?</h3><p>Наш трансфер по фиксированной цене в Land of Legends начинается от установленной ставки за автомобиль (не за человека). Точная цена отображается при бронировании. Никаких скрытых платежей.</p><h3>Можно ли заказать обратный трансфер из Land of Legends в аэропорт?</h3><p>Да, мы предлагаем трансферы туда и обратно. При бронировании вы можете выбрать обратный трансфер и получить скидку.</p><h3>Водитель ждёт у входа в парк?</h3><p>При заборе из отеля и обратных трансферах водитель будет на месте встречи в назначенное время. При прилёте мы отслеживаем рейс и встречаем вас в зале прилёта.</p>', 'Трансфер Land of Legends | Аэропорт Анталья — Land of Legends', 'Частный VIP-трансфер из аэропорта Анталья в парк развлечений Land of Legends в Белеке. ~30 мин, 35 км. Фиксированная цена, встреча в аэропорту, отслеживание рейса. Онлайн-бронирование.', 'Antalya Havalimanı → Land of Legends Transfer', 'Türkiye''nin en popüler tema parkına özel VIP transfer. Sabit fiyat, bekleme yok.', '<p>Land of Legends Tema Parkı, Antalya Havalimanı''nın yaklaşık 35 km doğusunda Belek''te yer almaktadır. TORVIAN''ın özel VIP transfer hizmetiyle yaklaşık 30 dakikada parka ulaşırsınız — taksi yok, bekleme yok, sürpriz yok.</p><h2>Neden TORVIAN?</h2><ul><li>Antalya Havalimanı (AYT)''ndan kapıdan kapıya direkt transfer</li><li>Sabit fiyat — taksimetre yok, gizli ücret yok</li><li>Varış salonunda isim tabelasıyla karşılama</li><li>Ücretsiz uçuş takibi — gecikmede bekliyoruz</li><li>Klimalı ve ücretsiz Wi-Fi''lı Mercedes Vito VIP</li><li>24 saate kadar ücretsiz iptal</li><li>7/24 Türkçe WhatsApp desteği</li></ul><h2>Sık Sorulan Sorular</h2><h3>Land of Legends Antalya Havalimanı''na ne kadar uzak?</h3><p>Belek''teki Land of Legends Tema Parkı, Antalya Havalimanı''na (AYT) yaklaşık 35 km uzaklıktadır. Özel araçla transfer yaklaşık 30 dakika sürmektedir.</p><h3>Land of Legends transferi ne kadar tutar?</h3><p>Land of Legends''a sabit fiyatlı transferimiz araç başına (kişi başına değil) belirli bir ücretle başlamaktadır. Kesin fiyat rezervasyon sırasında gösterilir. Gizli ücret yoktur.</p><h3>Land of Legends''tan havalimanına dönüş transferi rezervasyonu yapabilir miyim?</h3><p>Evet, gidiş-dönüş transferi sunuyoruz. Rezervasyon sırasında dönüş transferini seçerek indirimli kombinasyon fiyatından yararlanabilirsiniz.</p><h3>Şoför park girişinde bekliyor mu?</h3><p>Otel alımı ve dönüş transferlerinde şoförünüz belirlenen saatte buluşma noktasında olacaktır. Havalimanı varışlarında uçuşunuzu takip ediyor ve varış salonunda karşılıyoruz.</p>', 'Land of Legends Transfer | Antalya Havalimanı''ndan Land of Legends''a', 'Antalya Havalimanı''ndan Land of Legends Belek''e özel VIP transfer. ~30 dk, 35 km. Sabit fiyat, karşılama, uçuş takibi. Online rezervasyon yapın.', 'Luchthaven Antalya → Land of Legends Transfer', 'Privé VIP-transfer naar het populairste pretpark van Turkije. Vaste prijs, geen wachttijd.', '<p>Pretpark Land of Legends ligt in Belek, ongeveer 35 km ten oosten van de luchthaven Antalya. Met de privé VIP-transfer van TORVIAN bereikt u het park in ongeveer 30 minuten, volledig comfortabel — geen taxi''s, geen wachttijd, geen verrassingen.</p><h2>Waarom TORVIAN Boeken?</h2><ul><li>Directe deur-tot-deur transfer vanaf de luchthaven Antalya (AYT)</li><li>Vaste prijs — geen taxameter, geen piekprijzen</li><li>Ontvangst met naambord in de aankomsthal</li><li>Gratis vluchtmonitoring — wij wachten bij vertraging</li><li>Mercedes Vito VIP met airconditioning &amp; gratis wifi</li><li>Gratis annuleren tot 24 uur vooraf</li><li>24/7 WhatsApp-ondersteuning in het Nederlands</li></ul><h2>Veelgestelde vragen</h2><h3>Hoe ver ligt Land of Legends van de luchthaven Antalya?</h3><p>Pretpark Land of Legends in Belek ligt ongeveer 35 km van de luchthaven Antalya (AYT). De rit duurt met een privévoertuig ongeveer 30 minuten.</p><h3>Wat kost een transfer naar Land of Legends?</h3><p>Onze vasteprijstransfer naar Land of Legends begint bij een vast tarief per voertuig (niet per persoon). De exacte prijs wordt getoond tijdens het boeken. Geen verborgen kosten.</p><h3>Kan ik een retourtransfer van Land of Legends naar de luchthaven boeken?</h3><p>Ja, wij bieden retourtransfers aan. U kunt de retourtransfer tijdens het boeken selecteren en profiteren van een gecombineerde kortingsprijs.</p><h3>Wacht de chauffeur bij de parkingang?</h3><p>Bij ophaling vanaf het hotel en retourtransfers staat uw chauffeur op het afgesproken tijdstip op de ontmoetingsplek. Bij aankomst op het vliegveld volgen wij uw vlucht en ontvangen wij u in de aankomsthal.</p>', 'Land of Legends Transfer | Luchthaven Antalya naar Land of Legends', 'Privé VIP-transfer van de luchthaven Antalya naar het Land of Legends pretpark in Belek. ~30 min, 35 km. Vaste prijs, ontvangst met naambord, gratis vluchtmonitoring. Boek online.', 'Aeroportul Antalya → Transfer Land of Legends', 'Transfer privat VIP către cel mai popular parc tematic din Turcia. Preț fix, fără timp de așteptare.', '<p>Parcul tematic Land of Legends se află în Belek, la aproximativ 35 km est de Aeroportul Antalya. Cu transferul privat VIP TORVIAN ajungi la parc în circa 30 de minute, în tot confortul — fără taxiuri, fără așteptare, fără surprize.</p><h2>De ce să rezervi cu TORVIAN?</h2><ul><li>Transfer direct din ușă în ușă de la Aeroportul Antalya (AYT)</li><li>Preț fix — fără aparat de taxare, fără tarife majorate</li><li>Întâmpinare cu panou în holul de sosiri</li><li>Urmărirea zborului gratuită — așteptăm dacă ai întârziere</li><li>Mercedes Vito VIP cu aer condiționat și Wi-Fi gratuit</li><li>Anulare gratuită cu până la 24 de ore înainte</li><li>Asistență WhatsApp 24/7</li></ul><h2>Întrebări frecvente</h2><h3>La ce distanță este Land of Legends de Aeroportul Antalya?</h3><p>Parcul tematic Land of Legends din Belek se află la aproximativ 35 km de Aeroportul Antalya (AYT). Drumul durează în jur de 30 de minute cu un vehicul privat.</p><h3>Cât costă un transfer către Land of Legends?</h3><p>Transferul nostru cu preț fix către Land of Legends pornește de la un tarif fix per vehicul, nu per persoană. Prețul exact este afișat la rezervare. Fără costuri ascunse.</p><h3>Pot rezerva un transfer retur de la Land of Legends la aeroport?</h3><p>Da, oferim și transferuri retur. Poți selecta cursa de întoarcere la rezervare și beneficiezi de un preț redus pentru dus-întors.</p><h3>Șoferul așteaptă la intrarea în parc?</h3><p>La preluările de la hotel și la cursele de retur, șoferul te așteaptă la ora stabilită, în punctul de întâlnire convenit. La sosirea pe aeroport îți urmărim zborul și te întâmpinăm în holul de sosiri.</p>', 'Transfer Land of Legends | Aeroportul Antalya - Land of Legends', 'Transfer privat VIP de la Aeroportul Antalya la parcul tematic Land of Legends din Belek. ~30 min, 35 km. Preț fix, întâmpinare cu panou, urmărirea zborului gratuită. Rezervă online.'
WHERE NOT EXISTS (SELECT 1 FROM landing_pages WHERE slug = 'land-of-legends-transfer');
